import React, { useState } from 'react';
import axios from 'axios';

const Dashboard = () => {
  const [features, setFeatures] = useState({
    PM2_5: 75,
    CO: 10,
    NO2: 20,
    NH3: 30,
    O3: 60,
    Temp: 25,
    Humidity: 50,
    Pressure: 1013
  });

  const [result, setResult] = useState(null);

  const handleChange = (e) => {
    setFeatures({ ...features, [e.target.name]: parseFloat(e.target.value) });
  };

  const handlePredict = async () => {
    try {
      const response = await axios.post('http://localhost:5000/predict', {
        'PM2.5': features.PM2_5,
        'CO': features.CO,
        'NO2': features.NO2,
        'NH3': features.NH3,
        'O3': features.O3,
        'Temp': features.Temp,
        'Humidity': features.Humidity,
        'Pressure': features.Pressure
      });
      setResult(response.data.prediction);
    } catch (error) {
      console.error("Prediction error:", error);
      setResult("Error connecting to server");
    }
  };

  return (
    <div style={{ maxWidth: '600px', margin: '40px auto', backgroundColor: '#fff', color: '#000', padding: '20px', borderRadius: '12px', fontFamily: 'Arial', boxShadow: '0 0 12px rgba(0,0,0,0.1)' }}>
      <h2 style={{ textAlign: 'center' }}>Enter Input Features</h2>

      {[
        { label: 'PM2.5 (µg/m³)', name: 'PM2_5', min: 0, max: 2000 },
        { label: 'CO (µg/m³)', name: 'CO', min: 0, max: 58400 },
        { label: 'NO₂ (µg/m³)', name: 'NO2', min: 0, max: 3853 },
        { label: 'NH₃ (µg/m³)', name: 'NH3', min: 0, max: 300 },
        { label: 'O₃ (µg/m³)', name: 'O3', min: 0, max: 2350 },
        { label: 'Temperature (°C)', name: 'Temp', min: 0, max: 50 },
        { label: 'Humidity (%)', name: 'Humidity', min: 0, max: 100 },
        { label: 'Pressure (hPa)', name: 'Pressure', min: 900, max: 1100 }
      ].map((item) => (
        <div key={item.name} style={{ marginBottom: '20px' }}>
          <label>{item.label}</label>
          <div style={{ color: 'red', fontWeight: 'bold' }}>{features[item.name].toFixed(2)}</div>
          <input
            type="range"
            min={item.min}
            max={item.max}
            value={features[item.name]}
            name={item.name}
            onChange={handleChange}
            style={{ width: '100%' }}
          />
          <div style={{ display: 'flex', justifyContent: 'space-between', fontSize: '12px' }}>
            <span>{item.min.toFixed(2)}</span>
            <span>{item.max.toFixed(2)}</span>
          </div>
        </div>
      ))}

      <button
        onClick={handlePredict}
        style={{
          width: '100%',
          padding: '12px',
          backgroundColor: '#1976d2',
          color: '#fff',
          border: 'none',
          borderRadius: '6px',
          fontWeight: 'bold',
          fontSize: '16px',
          marginTop: '20px',
          cursor: 'pointer'
        }}
      >
        Predict EAQI
      </button>

      {result && (
        <div style={{ marginTop: '30px', textAlign: 'center', fontSize: '20px', fontWeight: 'bold', color: '#1976d2' }}>
          Prediction: {result}
        </div>
      )}
    </div>
  );
};

export default Dashboard;
